// Types of the test scenarios generated by tools/NodaJs.Tools scenarios into test/scenarios/**/*.generated.ts.

/** One NUnit fixture. */
export interface ScenarioFixture {
  /** NUnit full name, e.g. "NodaTime.Test.LocalDateTest". */
  readonly name: string;
  readonly source: string;
  /** Why the fixture's cases weren't exported (tools/scenario-exclusions.txt). */
  readonly excluded?: string;
  readonly tests: readonly ScenarioTest[];
}

/** One test method; a plain [Test] has one case with no arguments. */
export interface ScenarioTest {
  readonly method: string;
  /** "file:line" of the test body in the NodaTime repo. */
  readonly source: string;
  /** C# parameters, e.g. ["int days", "LocalDate expected"]. */
  readonly parameters?: readonly string[];
  /** Base class declaring the method, when inherited (e.g. "PatternTestBase"). */
  readonly declaredIn?: string;
  readonly excluded?: string;
  readonly ignored?: string;
  readonly explicit?: boolean;
  readonly notRunnable?: string;
  readonly skipped?: string;
  readonly cases: readonly ScenarioCase[];
}

export interface ScenarioCase {
  readonly args: readonly EncodedValue[];
  /** Present when the NUnit case has an ExpectedResult. */
  readonly expected?: EncodedValue;
  readonly description?: string;
  readonly ignored?: string;
  readonly explicit?: boolean;
  readonly notRunnable?: string;
  readonly encodingError?: string;
}

/** A value encoded by TsValueEncoder.cs: a primitive, an array or a tagged object ({ $: "LocalDate", ... }). */
export type EncodedValue =
  | null
  | boolean
  | number
  | bigint
  | string
  | readonly EncodedValue[]
  | EncodedObject;

export interface EncodedObject {
  readonly $: string;
  readonly [key: string]: unknown;
}
